export interface SeedCompany {
  id: string; name: string; parent_company: string | null; sector_id: string;
  headquarters_country: string; headquarters_city: string | null; india_entry_year: number | null;
  operating_status: 'active' | 'expanding' | 'downsizing' | 'closed' | 'announced';
  employee_count_india: number | null; description: string; website: string | null;
  source_id: string;
  locations: SeedCompanyLocation[];
}

